def load_model(registry_key, **kwargs):
    if registry_key not in MODEL_REGISTRY:
        raise ValueError(f"Model not found: {registry_key}")
    module_name = MODEL_REGISTRY[registry_key]
    class_name = registry_key.split(".")[-1]
    mod = importlib.import_module(module_name)
    cls = getattr(mod, class_name)
    return cls(**kwargs)

def list_models(category=None):
    if category:
        return [k for k in MODEL_REGISTRY if category in k.lower()]
    return list(MODEL_REGISTRY.keys())

if __name__ == "__main__":
    models = list_models()
    logging.info(f"Registry: {len(models)} models registered")
    for m in models[:5]:
        logging.info(f"  - {m}")
